                Action apply;
                if(preview!=null){preview.Initialize();var client=preview.GetComponent<PythonStateClient>();typeof(PythonStateClient).GetField("preview",f).SetValue(client,preview);apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});}
                else {state.new_game_options=new PythonNewGameOption[0];apply=()=>title.Apply(state);title.ApplySaves(new PythonSaveList{saves=new PythonSavedGame[0]});}
                apply();if(preview!=null){preview.GetComponent<PythonSavePanel>().Open();Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{preview,"Logs/PythonSaveEntryBusiness.png"});typeof(PythonStateClient).GetField("automatic",f).SetValue(preview.GetComponent<PythonStateClient>(),true);}else {title.ShowSaves();Canvas.ForceUpdateCanvases();typeof(PythonTitleSetup).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{"Logs/PythonSaveEntryTitle.png"});}
                if(title!=null && !title.continueGame.interactable)throw new Exception("Python entry unavailable without Unity saves");p.entry.onClick.Invoke();if(!p.panel.activeSelf || p.resume.interactable)throw new Exception("Initial import gate failed");if(preview!=null && preview.GetComponent<PythonStateClient>().Automatic)throw new Exception("Import did not pause automatic service");p.path.text="C:\\Games\\旧営業.json";if(!p.inspect.interactable)throw new Exception("Path input failed");
                var row=new PythonLegacySavePreview{save_id="preview-token",source_path=p.path.text,instance_id=state.instance_id,revision=state.revision,details="2日目 / 時刻 0 / 営業準備\n資金：500 / 在籍猫：3匹 / 席数：2\n猫：ミケ、タマ、ソラ\n経営ルール：未導入 / 病気ルール：有効\n\n現在の未保存の進捗は置き換わります。元のセーブと関係データは変更しません。再開後はUnity用の別セーブへ保存できます。"};p.AcceptPreview(row);if(!p.resume.interactable || !p.details.text.Contains("関係データ"))throw new Exception("Preview display failed");Canvas.ForceUpdateCanvases();
                if(preview!=null)typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{preview,"Logs/PythonSaveBusiness.png"});else typeof(PythonTitleSetup).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{"Logs/PythonSaveTitle.png"});
                p.path.text+="x";if(p.resume.interactable)throw new Exception("Edited path kept preview");p.AcceptPreview(row);state.revision++;apply();if(p.resume.interactable)throw new Exception("Changed state kept preview");row.revision=state.revision;p.AcceptPreview(row);p.Disconnect();if(p.resume.interactable)throw new Exception("Offline kept preview");apply();p.Open();row.details=new string('長',4000);p.AcceptPreview(row);Canvas.ForceUpdateCanvases();var scroll=p.details.GetComponentInParent<ScrollRect>();if(scroll.content.rect.height<=scroll.viewport.rect.height)throw new Exception("Import details did not scroll");p.Close();p.Open();if(p.resume.interactable)throw new Exception("Close kept preview");
                if(preview!=null){row.details="旧セーブ";p.AcceptPreview(row);p.resume.onClick.Invoke();var client=preview.GetComponent<PythonStateClient>();var command=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(command==null || command.kind!="load_python_game" || command.save_id!="preview-token" || command.working_cats.Length!=0 || p.resume.interactable)throw new Exception("Python load command incorrect");var id=command.request_id;p.Resume();if(((PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client)).request_id!=id)throw new Exception("Duplicate import queued");}
