        static void VerifyManagement()
        {
            EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,preview);var state=PythonServiceSetup.Sample();state.instance_id="legacy-management";state.objective_start=new PythonObjectiveStart{rows=new[]{new PythonStartObjective{choice="management",label="旧営業への経営ルール導入",can_start=true,details="病気ルールが有効な営業準備中に導入できます。\n資金：500 → 1000（補充：500）\n人気100、全猫のストレス0で開始します。\nストレス80以上で家出、帰還まで2日。\n資金または人気が0以下でゲームオーバーです。\n導入後の取消はできません。新規ゲーム専用の施設・イベントなどは追加しません。"}}};typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});var p=preview.GetComponent<PythonObjectiveStartPanel>();p.Open();p.tabs[3].onClick.Invoke();if(!p.proceed.interactable || !p.details.text.Contains("補充：500"))throw new Exception("Management tab failed");p.Choose();if(!p.confirmationText.text.Contains("ゲームオーバー"))throw new Exception("Management conditions missing");Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{preview,"Logs/LegacyManagement.png"});p.Cancel();if(typeof(PythonStateClient).GetField("pending",f).GetValue(client)!=null)throw new Exception("Management cancel queued");p.Choose();p.Confirm();var command=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(command.kind!="start_objective" || command.choice!="management")throw new Exception("Management command incorrect");Debug.Log("CAT_CAFE_LEGACY_MANAGEMENT_DISPLAY_OK");
        }
